using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Text.Json.Serialization;
using Korda.Data;

internal static class ControlRecordTests
{
    // Fixed bytes captured from the unmodified 7cf6c7d encoder, not generated by
    // the implementation under test. The five payloads have lengths 1..5.
    private static readonly byte[] EmptyGolden = Convert.FromHexString("01000d00100000000000000000000000");
    private static readonly byte[] FiveFieldGolden = Convert.FromHexString(
        "01000d006f000000050000000000000001000100010000006000000000000000" +
        "0200020002000000610000000000000003000300030000006300000000000000" +
        "0400040004000000660000000000000005000500050000006a00000000000000" +
        "001112222324333435364445464748");
    private const string BudgetEvidenceSha256 = "cd07281aa0651eb8d1cd3ea0f4ad88849d76730203bb073d300e52c2dcfe8516";

    internal static void Run(string output)
    {
        var assertions = 0;
        void Check(bool condition, string message)
        { assertions++; if (!condition) throw new InvalidOperationException(message); }
        void Reject<T>(Action action, string message, string? parameter = null) where T : Exception
        {
            try { action(); }
            catch (Exception error)
            {
                Check(error.GetType() == typeof(T) && error.Message == message,
                    "ControlRecord exception type or message changed: " + error);
                if (parameter is not null)
                    Check(error is ArgumentException argument && argument.ParamName == parameter,
                        "ControlRecord exception parameter changed.");
                return;
            }
            throw new InvalidOperationException("ControlRecord accepted an invalid input.");
        }

        var ordered = CreateFiveFields();
        ControlField[][] permutations = [ordered,
            [ordered[4], ordered[3], ordered[2], ordered[1], ordered[0]],
            [ordered[2], ordered[0], ordered[4], ordered[1], ordered[3]]];
        foreach (var fields in permutations)
        {
            var references = (ControlField[])fields.Clone();
            var payloads = fields.Select(field => (byte[])field.Bytes.Clone()).ToArray();
            var encoded = ControlRecord.Encode(13, fields);
            Check(encoded.AsSpan().SequenceEqual(FiveFieldGolden), "ControlRecord fixed five-field golden changed.");
            for (var i = 0; i < fields.Length; i++)
            {
                Check(ReferenceEquals(fields[i], references[i]), "ControlRecord mutated the caller's field order.");
                Check(fields[i].Bytes.AsSpan().SequenceEqual(payloads[i]), "ControlRecord mutated an input payload.");
            }
            var second = ControlRecord.Encode(13, fields);
            Check(!ReferenceEquals(encoded, second), "ControlRecord reused a caller-owned result array.");
            encoded[^1] ^= 0xff;
            Check(second.AsSpan().SequenceEqual(FiveFieldGolden), "Mutating one result affected another result.");
            for (var i = 0; i < fields.Length; i++)
                Check(fields[i].Bytes.AsSpan().SequenceEqual(payloads[i]), "Output storage aliases an input payload.");
            var original = fields[0].Bytes[0];
            fields[0].Bytes[0] ^= 0xff;
            Check(second.AsSpan().SequenceEqual(FiveFieldGolden), "Returned wire bytes still borrow an input payload.");
            fields[0].Bytes[0] = original;
        }
        Check(ControlRecord.Encode(13, []).AsSpan().SequenceEqual(EmptyGolden), "Empty ControlRecord golden changed.");
        var maximumIdGolden = Convert.FromHexString("01000d00200000000100000000000000ffff0000000000002000000000000000");
        Check(ControlRecord.Encode(13, new ControlField(ushort.MaxValue, 0, [])).AsSpan().SequenceEqual(maximumIdGolden),
            "Positive noncontiguous/max IDs or an empty payload gained a new restriction.");

        var nullMessage = new NullReferenceException().Message;
        var invalidIds = "Invalid control field IDs.";
        Reject<ArgumentNullException>(() => ControlRecord.Encode(13, null!), new ArgumentNullException("source").Message, "source");
        Reject<NullReferenceException>(() => ControlRecord.Encode(13, new ControlField[] { null! }), nullMessage);
        Reject<NullReferenceException>(() => ControlRecord.Encode(13, new ControlField(1, 1, null!)), nullMessage);
        Reject<ArgumentException>(() => ControlRecord.Encode(13, new ControlField(0, 1, [1])), invalidIds);
        Reject<ArgumentException>(() => ControlRecord.Encode(13, new ControlField(1, 1, [1]), new(1, 2, [2])), invalidIds);
        Reject<NullReferenceException>(() => ControlRecord.Encode(13, new ControlField(1, 1, [1]), new(1, 2, [2]), null!), nullMessage);
        Reject<NullReferenceException>(() => ControlRecord.Encode(13, new ControlField(0, 1, [1]), null!), nullMessage);
        Reject<ArgumentException>(() => ControlRecord.Encode(13, new ControlField(0, 1, null!)), invalidIds);
        Reject<ArgumentException>(() => ControlRecord.Encode(13, new ControlField(1, 1, null!), new(1, 2, [2])), invalidIds);

        // The accepted boundary is a complete 4 MiB record, including its header.
        const int maximumEncodedBytes = 4 * 1024 * 1024;
        var atLimit = new byte[maximumEncodedBytes - 32];
        atLimit[0] = 0x12; atLimit[^1] = 0x7f;
        var boundary = ControlRecord.Encode(13, new ControlField(1, 1, atLimit));
        var boundaryHeader = Convert.FromHexString("01000d0000004000010000000000000001000100e0ff3f002000000000000000");
        Check(boundary.Length == maximumEncodedBytes && boundary.AsSpan(0, 32).SequenceEqual(boundaryHeader)
            && boundary.AsSpan(32).SequenceEqual(atLimit), "ControlRecord exact size boundary changed.");
        Reject<ArgumentException>(() => ControlRecord.Encode(13, new ControlField(1, 1, new byte[atLimit.Length + 1])),
            "Control record exceeds limit.");

        // Shared test payloads exercise checked length arithmetic without a
        // multi-gigabyte allocation. The old encoder throws OverflowException
        // before its size-limit check in both cases; IDs remain valid and ordered.
        const int fieldCount = 2048, payloadBytes = 1024 * 1024;
        var shared = new byte[payloadBytes];
        var overflow = new ControlField[fieldCount];
        for (var i = 0; i < overflow.Length; i++) overflow[i] = new((ushort)(i + 1), 1, shared);
        Reject<OverflowException>(() => ControlRecord.Encode(13, overflow), new OverflowException().Message);
        var headerBytes = 16 + fieldCount * 16;
        var lastPayloadBytes = checked((int)((long)int.MaxValue + 1 - headerBytes - (long)(fieldCount - 1) * payloadBytes));
        overflow[^1] = new((ushort)fieldCount, 1, new byte[lastPayloadBytes]);
        Reject<OverflowException>(() => ControlRecord.Encode(13, overflow), new OverflowException().Message);

        File.WriteAllBytes(Path.Combine(output, "control-record-five-fields.bin"), FiveFieldGolden);
        File.WriteAllBytes(Path.Combine(output, "control-record-empty.bin"), EmptyGolden);
        File.WriteAllText(Path.Combine(output, "control-record-assertions.txt"),
            assertions.ToString(System.Globalization.CultureInfo.InvariantCulture));
    }

    internal static void RunAllocation(string output)
    {
        if (RuntimeFeature.IsDynamicCodeSupported || !OperatingSystem.IsLinux()
            || RuntimeInformation.ProcessArchitecture != Architecture.X64)
            throw new InvalidOperationException("ControlRecord allocation regression requires Linux x64 Native AOT.");

        const int warmup = 2048, operations = 8192, repeats = 3;
        const int measuredBeforeBytesPerOperation = 1064, maximumBytesPerOperation = 136;
        var fields = CreateFiveFields();
        var samples = new ControlRecordAllocationSample[repeats];
        if (!ControlRecord.Encode(13, fields).AsSpan().SequenceEqual(FiveFieldGolden))
            throw new InvalidOperationException("ControlRecord allocation fixture differs from the fixed golden.");
        var expectedChecksum = Consume(FiveFieldGolden) * operations;
        long warmChecksum = 0;
        for (var i = 0; i < warmup; i++) warmChecksum += Consume(ControlRecord.Encode(13, fields));
        if (warmChecksum != Consume(FiveFieldGolden) * warmup)
            throw new InvalidOperationException("ControlRecord warmup result changed.");
        _ = Stopwatch.GetTimestamp(); _ = GC.GetTotalAllocatedBytes(true);
        _ = GC.CollectionCount(0); _ = GC.CollectionCount(1); _ = GC.CollectionCount(2);
        for (var repeat = 0; repeat < repeats; repeat++)
        {
            var gen0Before = GC.CollectionCount(0); var gen1Before = GC.CollectionCount(1); var gen2Before = GC.CollectionCount(2);
            var started = Stopwatch.GetTimestamp(); var before = GC.GetTotalAllocatedBytes(true);
            long checksum = 0;
            for (var i = 0; i < operations; i++) checksum += Consume(ControlRecord.Encode(13, fields));
            var after = GC.GetTotalAllocatedBytes(true); var ended = Stopwatch.GetTimestamp();
            var gen0After = GC.CollectionCount(0); var gen1After = GC.CollectionCount(1); var gen2After = GC.CollectionCount(2);
            samples[repeat] = new(repeat, operations, before, after, after - before,
                gen0Before, gen0After, gen1Before, gen1After, gen2Before, gen2After, checksum, ended - started);
        }

        var receipt = new ControlRecordAllocationReceipt("DB-Perf-01", "internal-control-record-short-regression", true,
            RuntimeInformation.FrameworkDescription, RuntimeInformation.ProcessArchitecture.ToString(), warmup,
            FiveFieldGolden.Length, measuredBeforeBytesPerOperation, maximumBytesPerOperation, BudgetEvidenceSha256,
            "Raw whole-process GC.GetTotalAllocatedBytes(true); prebuilt fields/payloads, warmup and reporting are outside. Each operation includes actual internal Encode and complete output byte consumption. No subtraction, SQL, public PackageReference or concurrency-coverage claim.",
            "The owned wire byte[] and encoder temporary allocations are framework allocation. Unexplained process bytes must not be reassigned to business objects. The 136 B/op ceiling is the observed after value in each of three independent AOT processes; whole Encode is not 0 B.",
            "Business-result allocation is 0 only because this fixture produces no business DTO/list/string result. GC before/after counts cover the shared process heap and are not assigned to business/framework buckets.",
            0, false, Stopwatch.Frequency, samples);
        File.WriteAllText(Path.Combine(output, "control-record-allocation.json"),
            JsonSerializer.Serialize(receipt, ControlRecordTestJson.Default.ControlRecordAllocationReceipt));
        foreach (var sample in samples)
        {
            if (sample.Checksum != expectedChecksum)
                throw new InvalidOperationException("ControlRecord measured result consumption changed.");
            if (sample.AllocatedBytes <= 0 || sample.AllocatedBytes > (long)maximumBytesPerOperation * sample.Operations)
                throw new InvalidOperationException($"ControlRecord raw allocation {sample.AllocatedBytes} B / {sample.Operations} operations exceeds the measured {maximumBytesPerOperation} B/op bound or lost its owned output allocation.");
        }
        GC.KeepAlive(fields);
        Console.WriteLine("PASS ControlRecord framework allocation <=136 B/op; owned output arrays remain included and all raw process/GC counters retained.");
    }

    private static ControlField[] CreateFiveFields() =>
    [
        new(1, 1, [0x00]), new(2, 2, [0x11, 0x12]), new(3, 3, [0x22, 0x23, 0x24]),
        new(4, 4, [0x33, 0x34, 0x35, 0x36]), new(5, 5, [0x44, 0x45, 0x46, 0x47, 0x48]),
    ];

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static long Consume(byte[] bytes)
    { long checksum = 0; for (var i = 0; i < bytes.Length; i++) checksum += bytes[i]; return checksum; }
}

internal readonly record struct ControlRecordAllocationSample(int Repeat, int Operations,
    long AllocatedBefore, long AllocatedAfter, long AllocatedBytes,
    int Gen0Before, int Gen0After, int Gen1Before, int Gen1After, int Gen2Before, int Gen2After,
    long Checksum, long ElapsedTicks);
internal sealed record ControlRecordAllocationReceipt(string Task, string Kind, bool NativeAot,
    string Runtime, string Architecture, int WarmupOperations, int EncodedBytes,
    int MeasuredBeforeBytesPerOperation, int MaximumBytesPerOperation, string BudgetEvidenceComparisonSha256,
    string Scope, string FrameworkAllocationScope, string BusinessAndGcScope,
    int BusinessResultBytesPerOperation, bool WholeEncodeZeroBytes, long StopwatchFrequency,
    ControlRecordAllocationSample[] Samples);
[JsonSerializable(typeof(ControlRecordAllocationReceipt))]
internal partial class ControlRecordTestJson : JsonSerializerContext { }
